#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>

int sum_in_child(const int *values, int n, long *result) {
    int fd[2];
    if (pipe(fd) != 0) {
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        /* fork failed: close both ends in the parent */
        close(fd[0]);
        close(fd[1]);
        return -1;
    }

    if (pid == 0) {
        /* Child: close the read end, compute the sum, write it, exit */
        close(fd[0]);

        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += values[i];
        }

        if (write(fd[1], &sum, sizeof(sum)) != (ssize_t) sizeof(sum)) {
            close(fd[1]);
            _exit(1);
        }

        close(fd[1]);
        _exit(0);
    }

    /* Parent: close the write end, read the sum, wait for the child */
    close(fd[1]);

    long local_result;
    ssize_t nread = read(fd[0], &local_result, sizeof(local_result));
    close(fd[0]);

    if (nread != (ssize_t) sizeof(local_result)) {
        /* Could not read a complete long (EOF or partial read) */
        /* Reap the child before returning */
        int status;
        waitpid(pid, &status, 0);
        return -1;
    }

    int status;
    if (waitpid(pid, &status, 0) != pid) {
        return -1;
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        return -1;
    }

    *result = local_result;
    return 0;
}
