import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Comparator;
import java.util.stream.Collectors;

public class Report {

    public record Student(String name, String group, java.util.List<Integer> grades) {
    }

    private static double mean(java.util.List<Integer> grades) {
        if (grades == null || grades.isEmpty()) {
            return Double.NaN;
        }
        return grades.stream().mapToInt(Integer::intValue).average().orElse(Double.NaN);
    }

    private static boolean hasGrades(java.util.List<Integer> grades) {
        return grades != null && !grades.isEmpty();
    }

    public static java.util.Map<String, Double> averageByGroup(java.util.List<Student> students) {
        return students.stream()
                .filter(s -> hasGrades(s.grades()))
                .collect(Collectors.groupingBy(
                        Student::group,
                        Collectors.mapping(
                                Report::mean,
                                Collectors.collectingAndThen(
                                        Collectors.toList(),
                                        list -> list.stream().mapToInt(Double::doubleValue).average()
                                                .orElseThrow()
                                )
                        )
                ));
    }

    public static java.util.List<String> topStudents(java.util.List<Student> students, int n) {
        return students.stream()
                .filter(s -> hasGrades(s.grades()))
                .sorted(Comparator.comparing(Report::mean).reversed()
                        .thenComparing(Student::name))
                .limit(n)
                .map(Student::name)
                .collect(Collectors.toList());
    }

    public static Optional<Student> best(java.util.List<Student> students, String group) {
        return students.stream()
                .filter(s -> group.equals(s.group()))
                .filter(s -> hasGrades(s.grades()))
                .max(Comparator.comparing(Report::mean));
    }
}
