#ifndef SCENE_HPP
#define SCENE_HPP

#include <cmath>
#include <cstddef>
#include <limits>
#include <memory>
#include <ostream>
#include <stdexcept>
#include <string>
#include <vector>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::string name() const = 0;
    virtual std::unique_ptr<Shape> clone() const = 0;
};

class Circle : public Shape {
public:
    explicit Circle(double r) : radius_(r) {
        if (!(r > 0.0)) {
            throw std::invalid_argument("radius must be > 0");
        }
    }

    double area() const override {
        return 3.14159265358979 * radius_ * radius_;
    }

    std::string name() const override {
        return "circle";
    }

    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Circle>(radius_);
    }

private:
    double radius_;
};

class Rect : public Shape {
public:
    Rect(double w, double h) : width_(w), height_(h) {
        if (!(w > 0.0) || !(h > 0.0)) {
            throw std::invalid_argument("width and height must be > 0");
        }
    }

    double area() const override {
        return width_ * height_;
    }

    std::string name() const override {
        return "rect";
    }

    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Rect>(width_, height_);
    }

private:
    double width_;
    double height_;
};

class Scene {
public:
    Scene() = default;

    Scene(const Scene& other) {
        for (const auto& s : other.shapes_) {
            shapes_.push_back(s->clone());
        }
    }

    Scene& operator=(const Scene& other) {
        if (this != &other) {
            shapes_.clear();
            for (const auto& s : other.shapes_) {
                shapes_.push_back(s->clone());
            }
        }
        return *this;
    }

    void add(std::unique_ptr<Shape> s) {
        if (!s) {
            throw std::invalid_argument("shape cannot be null");
        }
        shapes_.push_back(std::move(s));
    }

    std::size_t size() const {
        return shapes_.size();
    }

    double total_area() const {
        double total = 0.0;
        for (const auto& s : shapes_) {
            total += s->area();
        }
        return total;
    }

    std::string largest() const {
        if (shapes_.empty()) {
            throw std::runtime_error("scene is empty");
        }
        const Shape* best = shapes_[0].get();
        for (const auto& s : shapes_) {
            if (s->area() > best->area()) {
                best = s.get();
            }
        }
        return best->name();
    }

private:
    std::vector<std::unique_ptr<Shape>> shapes_;
};

inline std::ostream& operator<<(std::ostream& os, const Scene& scene) {
    std::vector<const Shape*> sorted;
    sorted.reserve(scene.shapes_.size());
    for (const auto& s : scene.shapes_) {
        sorted.push_back(s.get());
    }
    std::sort(sorted.begin(), sorted.end(),
              [](const Shape* a, const Shape* b) {
                  return a->area() < b->area();
              });

    os.precision(2);
    os << std::fixed;
    for (std::size_t i = 0; i < sorted.size(); ++i) {
        if (i != 0) {
            os << ' ';
        }
        os << sorted[i]->name() << ':' << sorted[i]->area();
    }
    return os;
}

#endif // SCENE_HPP
